//
// Console D3D12 ABI editions. The vtables of d3d12_xs.h change between GDK releases (methods
// are inserted mid-table), and a title calls the layout of the GDK it was built with. The layer
// implements the pinned SDK's layout; for a title built with an older GDK (its .xbld section
// names the edition, e.g. "GXDK,220300"), objects get a copy of their table rearranged into
// that edition's order (layouts generated by tools/gen/gen_abi_layouts.py from older headers).
#pragma once
#include <cstddef>

namespace xs::abi {
// The title's GXDK edition (e.g. 220300), 0 if unknown. Read once from the main executable.
unsigned title_edition();
// The table to install in an object: `native` itself, or its rearrangement for the title's ABI.
void* select(void* native, const char* name, size_t bytes);

template <class T> struct TableName { static constexpr const char* value = nullptr; };
}  // namespace xs::abi

#define XSL_ABI_TABLE(T) \
    template <> struct xs::abi::TableName<T##_Function_Table> { static constexpr const char* value = #T; };
